-- Additive private immutable normalized history. No existing tables are changed.
PRAGMA foreign_keys=ON;
CREATE TABLE sc_series (series_id TEXT PRIMARY KEY, source_id TEXT NOT NULL, policy_version TEXT NOT NULL, configuration_hash TEXT NOT NULL CHECK(length(configuration_hash)=64 AND configuration_hash NOT GLOB '*[^0-9a-f]*'), stats_code TEXT NOT NULL CHECK(stats_code IN ('00550200','00550300')), table_title TEXT NOT NULL, item_code TEXT NOT NULL, item_name_ja TEXT NOT NULL, measure TEXT NOT NULL, unit_raw TEXT NOT NULL, unit_norm TEXT, base_year INTEGER, definition_version_id TEXT NOT NULL, public_json TEXT NOT NULL CHECK(json_valid(public_json)));
CREATE TABLE sc_definition_versions (definition_version_id TEXT PRIMARY KEY, series_id TEXT NOT NULL REFERENCES sc_series(series_id), valid_from_year INTEGER CHECK(valid_from_year IS NULL OR valid_from_year BETWEEN 1900 AND 9999), item_name_ja TEXT NOT NULL, unit_raw TEXT NOT NULL, source_table_id TEXT NOT NULL, mapping_note TEXT, public_json TEXT NOT NULL CHECK(json_valid(public_json)));
CREATE TABLE sc_observations (obs_id TEXT PRIMARY KEY, series_id TEXT NOT NULL REFERENCES sc_series(series_id), definition_version_id TEXT NOT NULL REFERENCES sc_definition_versions(definition_version_id), batch_id TEXT NOT NULL, source_id TEXT NOT NULL, policy_version TEXT NOT NULL, configuration_hash TEXT NOT NULL CHECK(length(configuration_hash)=64 AND configuration_hash NOT GLOB '*[^0-9a-f]*'), period TEXT NOT NULL, value_decimal TEXT CHECK(value_decimal IS NULL OR (length(value_decimal) BETWEEN 1 AND 100 AND (substr(ltrim(value_decimal,'-'),1,1)<>'0' OR length(ltrim(value_decimal,'-'))=1 OR substr(ltrim(value_decimal,'-'),2,1)='.') AND value_decimal NOT GLOB '*[^0-9.-]*' AND value_decimal GLOB '*[0-9]*' AND length(value_decimal)-length(replace(value_decimal,'.',''))<=1 AND (instr(value_decimal,'-')=0 OR (substr(value_decimal,1,1)='-' AND instr(substr(value_decimal,2),'-')=0)) AND substr(value_decimal,1,1)<>'.' AND substr(value_decimal,-1)<>'.' AND substr(value_decimal,1,2)<>'-.')), value_flag TEXT, release_kind TEXT NOT NULL CHECK(release_kind IN ('annual','iip_monthly')), stats_data_id TEXT NOT NULL, source_updated_at TEXT, fetched_at TEXT NOT NULL, response_sha256 TEXT NOT NULL CHECK(length(response_sha256)=64 AND response_sha256 NOT GLOB '*[^0-9a-f]*'), supersedes_obs_id TEXT, expires_at TEXT NOT NULL, public_json TEXT NOT NULL CHECK(json_valid(public_json)), CHECK((value_decimal IS NULL AND value_flag IS NOT NULL) OR (value_decimal IS NOT NULL AND value_flag IS NULL)), CHECK(obs_id<>supersedes_obs_id));
CREATE INDEX sc_observations_series_period ON sc_observations(series_id,period,fetched_at,obs_id);
CREATE INDEX sc_observations_policy_expiry ON sc_observations(source_id,policy_version,expires_at);
CREATE TABLE sc_revisions (revision_id TEXT PRIMARY KEY, series_id TEXT NOT NULL REFERENCES sc_series(series_id), before_obs_id TEXT NOT NULL REFERENCES sc_observations(obs_id), after_obs_id TEXT NOT NULL REFERENCES sc_observations(obs_id), detected_at TEXT NOT NULL, public_json TEXT NOT NULL CHECK(json_valid(public_json)), CHECK(before_obs_id<>after_obs_id));
CREATE INDEX sc_revisions_series ON sc_revisions(series_id,detected_at,revision_id);
CREATE TRIGGER sc_series_immutable BEFORE UPDATE ON sc_series BEGIN SELECT RAISE(ABORT,'sc_series_immutable'); END;
CREATE TRIGGER sc_definitions_immutable BEFORE UPDATE ON sc_definition_versions BEGIN SELECT RAISE(ABORT,'sc_definitions_immutable'); END;
CREATE TRIGGER sc_observations_immutable BEFORE UPDATE ON sc_observations BEGIN SELECT RAISE(ABORT,'sc_observations_immutable'); END;
CREATE TRIGGER sc_revisions_immutable BEFORE UPDATE ON sc_revisions BEGIN SELECT RAISE(ABORT,'sc_revisions_immutable'); END;
-- Bounded monthly intake checkpoints. A reserved request is never issued again after a crash.
CREATE TABLE sc_intakes (run_id TEXT PRIMARY KEY REFERENCES collection_runs(run_id), configuration_hash TEXT NOT NULL, phase TEXT NOT NULL CHECK(phase IN ('list','data','rows','complete','failed','quarantined')), list_start INTEGER NOT NULL DEFAULT 1, list_pages INTEGER NOT NULL DEFAULT 0, tables_json TEXT NOT NULL DEFAULT '[]' CHECK(json_valid(tables_json)), table_index INTEGER NOT NULL DEFAULT 0, data_start INTEGER NOT NULL DEFAULT 1, data_pages INTEGER NOT NULL DEFAULT 0, row_index INTEGER NOT NULL DEFAULT 0, page_ref TEXT, page_hash TEXT, page_next INTEGER, schema_signature TEXT, request_reserved INTEGER NOT NULL DEFAULT 0 CHECK(request_reserved IN (0,1)), publication_batch TEXT NOT NULL);
CREATE TABLE sc_schema_history (source_id TEXT NOT NULL, table_group TEXT NOT NULL, schema_signature TEXT NOT NULL, first_run_id TEXT NOT NULL REFERENCES collection_runs(run_id), PRIMARY KEY(source_id,table_group));
CREATE TRIGGER sc_schema_history_immutable BEFORE UPDATE ON sc_schema_history BEGIN SELECT RAISE(ABORT,'sc_schema_history_immutable'); END;
